  meaning: 'Om е най-свещената сричка в индуизма — звукът, от който е създадена Вселената. Състои се от три звука: A (сътворение), U (поддържане), M (разтваряне). Мълчанието след нея е четвъртото състояние — чистото съзнание.',
  detailed: `Om (или Aum) се споменава за първи път в Упанишадите, най-старите философски текстове на Индия (около 800-500 г. пр. Хр.). Смята се, че това е първият звук, който е прозвучал при сътворението на света — вибрацията, която все още резонира във всяка атомна частица. В Мандукя Упанишад се обяснява, че четирите части на Aum отговарят на четирите състояния на съзнанието: будно състояние (A), сънуване (U), дълбок сън (M) и трансцендентно съзнание (мълчанието). Практикуващите повтарят Om, за да се свържат с първичната вибрация на съществуването. Може да се повтаря на глас, шепнешком или мислено. Всеки от трите звука трябва да се произнася дълго и пълно, като вибрацията се усеща в гърдите, гърлото и главата.`,
