  detailed: `Gayatri Mantra се среща в Риг Веда (3.62.10) и е на възраст над 3000 години. Традиционно се предава от гуру на ученик при ритуала Упанаяна — посвещаване в ученичество. Мантрата се състои от 24 срички, които символизират 24-те принципа на природата. Първите три думи — Bhūr, Bhuvaḥ, Svaḥ — представляват трите свята: земя, атмосфера, небе. Savitur е богът на Слънцето, който дава живот. Vareṇyaṃ означава този, който е достоен за почитане. Bhargo Devasya означава божествената светлина. Dhīmahi означава съзерцаваме. Dhiyo Yo Naḥ Prachodayāt означава нека той просветли нашите мисли. Практикува се на разсъмване, обед и залез.`,
