  transliteration: 'Om Tryambakaṃ Yajāmahe Sugandhiṃ Puṣṭi-vardhanam Urvārukam-iva Bandhanān Mṛtyor-Mukṣīya Māamṛtāt',
  translation: 'Ом. Почитаме Триокия (Шива). Нека той, който е благоуханен и храни всички, ни освободи от смъртта, като краставица от лозата — и ни дари с безсмъртие.',
  tradition: 'Индуистка (Риг Веда)',
  deity: 'Шива (Триоката)',
  theme: 'healing',
  meaning: 'Maha Mrityunjaya е мантрата, която побеждава смъртта. Известна е още като Tryambakam Mantra. Тя не е молитва да не умреш — а да се освободиш от страха от смъртта и да намериш безсмъртие в духа.',
  detailed: `Maha Mrityunjaya Mantra се среща в Риг Веда (7.59.12) и е една от най-старите мантри за изцеление в света. Наричана е Мантрата на трите очи (Tryambakam), защото е посветена на Шива, който има трето око. Думата Mrityunjaya означава победител на смъртта — от mrityu (смърт) и jaya (победа). Традиционно се използва при болест, тежка диагноза, за предпазване от злополуки и за изцеление на физическо, емоционално и духовно ниво. Мантрата се състои от 8 срички. Urvārukam-iva Bandhanān е красива метафора — краставицата, която е здраво привързана към лозата, но когато узрее, се откъсва без усилие. Така и ние трябва да се освободим от света без борба.`,
