  meaning: 'Om Namah Shivaya е една от най-разпознаваемите мантри в света. Тя е поздрав и поклон пред Шива — богът на трансформацията, разрушението и прераждането. Наричана е още Панчакшара Мантра (петсрична мантра), защото се състои от пет срички: Na-Ma-Śi-Vā-Ya.',
  detailed: `Om Namah Shivaya е централната мантра на шиваизма — най-старата жива религия в света. Петте срички Na-Ma-Śi-Vā-Ya представляват петте елемента: земя, вода, огън, въздух, етер — и петте сетива. Namaḥ означава поклон, отдаване. Śivāya означава на Шива. Практикува се както в храм, така и в ежедневието — може да се повтаря при ходене, готвене, шофиране. Смята се, че ако човек повтаря тази мантра с искрено сърце, Шива му помага да се освободи от егото и да постигне вътрешен мир. Тя е мост между предаността и себепознанието.`,
