  meaning: 'Hare Krishna е известна като Маха Мантра (великата мантра) в традицията на вайшнавизма. Тя е призив към Бога в неговите форми Кришна и Рама, и към неговата енергия Харе.',
  detailed: `Hare Krishna Mantra е популяризирана на Запад от Шрила Прабхупада и движението ISKCON през 60-те години на 20-ти век. Всъщност мантрата е древна — споменава се в Кали-сантарана Упанишад и в Пураните. Състои се от 16 думи (32 срички), които представляват 32 аспекта на Божественото. Hare означава енергията на Бога (Радха), Krishna означава Всепривличащият, Rama означава Всерадващият. Прабхупада я разпространява по целия свят, като нейните последователи я пеят по улиците. Мантрата може да се пее, шепне или мисли.`,
  benefit: 'Любов към Бога, освобождаване от егото, вътрешно удовлетворение.',
