  theme: 'protection',
  meaning: 'Om Namo Narayanaya е осемсрична мантра, посветена на Вишну — пазителят на Вселената. Нараяна означава този, който лежи върху водите — символ на съзнанието, което почива върху безкрайния океан на съществуването.',
  detailed: `Тази мантра се среща в Narayana Upanishad и във Вишну Пурана. Нараяна е едно от най-старите имена на Бога в индуизма — среща се още в Риг Веда. Nara означава води или човешки същества, а yana означава този, който се движи. Така Нараяна е едновременно Богът в сърцата на всички същества и океанът на съзнанието, върху който Вселената почива. Мантрата е защитна по своята същност. Традиционно се предава от гуру на ученик при посвещение (дикша). Свами Шивананда я препоръчва като една от най-мощните мантри за ежедневна практика.`,
