  id: 'om_gan_ganpataye_namah',
  name: 'Om Gam Ganpataye Namah',
  sanskrit: 'ॐ गं गणपतये नमः',
  transliteration: 'Oṃ Gaṃ Gaṇapataye Namaḥ',
  translation: 'Ом. Отдавам почит на Ганеша, господарят на ганите.',
