  deity: 'Ганеша',
  theme: 'protection',
  meaning: 'Това е мантрата на Ганеша — богът с глава на слон, който премахва пречките и носи успех във всяко начинание. Ganapati означава господар на ганите (групите същества). Сричката Gam е биджа мантрата (семенна мантра) на Ганеша.',
  detailed: `Om Gam Ganpataye Namah е една от най-популярните мантри за начинания в индуизма. Традиционно се повтаря преди започване на нов проект, пътуване, сватба, изпит, бизнес. Ганеша е син на Шива и Парвати, и е почитан като Vighnaharta — този, който премахва пречките. Историята разказва как Ганеша получил слонска глава, след като Шива отрязал първоначалната му глава. Слонът символизира мъдрост, памет и интелигентност. Мантрата се състои от три части: Om, Gam, Ganpataye Namah. Gam е звукът, който активира енергията на Ганеша.`,
  benefit: 'Премахва пречки, носи успех, пази начинанията.',
  repetitions: '108 пъти преди важни събития',
