  translation: 'Ом. Отдавам почит на Бога, който е син на Васудева (Кришна).',
  tradition: 'Индуистка (Вайшнава)',
  deity: 'Кришна',
  theme: 'devotion',
  meaning: 'Тази мантра е посветена на Кришна — въплъщението на Вишну на Земята. Vasudeva означава син на Васудева (Кришна) и този, който живее във всички неща.',
  detailed: `Om Namo Bhagavate Vasudevaya е една от най-мощните мантри във вайшнавизма. Среща се в Bhagavad Gita, Vishnu Purana и Bhagavata Purana. Думата Vasudeva може да се раздели на две: vas (живея) + deva (Бог) — Богът, който живее във всичко. Също така е името на бащата на Кришна — Васудева. В Bhagavad Gita (7.19) Кришна казва: След много раждания, този, който знае, че Васудева е всичко, ме намира. Мантрата се смята за Moksha Mantra — мантра за освобождение. Традицията казва, че който повтаря тази мантра с преданост, постига освобождение.`,
  benefit: 'Освобождение (moksha), преданост, връзка с Кришна.',
