  detailed: `Om Shanti Shanti Shanti е една от най-често срещаните мантри в индуистките писания — появява се в края на почти всяка молитва, ритуал или Упанишада. Тройното повторение не е случайно: в индийската философия има три свята, три състояния на съзнанието, три гуни, три вида страдание. Повтарянето на Shanti три пъти е за защита от всички тези нива на страдание. Om е първичният звук, който свързва мантрата с цялата Вселена. Мантрата се използва в края на медитация, при молитва, при сбогуване с учител или при завършване на ритуал. Също така се използва при конфликт — за успокояване на напрежението.`,
  benefit: 'Вътрешен мир, спокойствие, защита от страдание.',
