  transliteration: 'Oṃ Hrīṃ Śrīṃ Krīṃ Kālikāyai Namaḥ',
  translation: 'Ом. Хрим, Шрим, Крим — на Каликая (Кали).',
  tradition: 'Индуистка (Тантра)',
