  detailed: `Ya Devi Sarva Bhuteshu е една от най-красивите молитви в Деви Махатмя. Тя се състои от множество строфи, всяка от които започва с Yā Devī Sarva Bhūteṣu — „Богинята, която е във всички същества" — и продължава с конкретно качество: Śakti Rūpeṇa (под формата на сила), Buddhi Rūpeṇa (под формата на интелект), Śraddhā Rūpeṇa (под формата на вяра), Lajjā Rūpeṇa (под формата на скромност), Śānti Rūpeṇa (под формата на мир), Dayā Rūpeṇa (под формата на състрадание). Всяка строфа завършва с тройно Namastasyai — „поклон на нея". Тройното повторение е характерно за индийската традиция — то показва пълно отдаване на тялото, речта и ума. Молитвата се използва за преданост, за защита, за свързване с Богинята във всичките ѝ форми. Тя се рецитира в края на Деви Махатмя или самостоятелно. Много практикуващи я рецитират всеки ден.`,
  benefit: 'Преданост, защита, свързване с Богинята във всички форми.',
