  detailed: `Om Yamunayai Namah е мантра, посветена на Ямуна — богинята на река Ямуна. Yamunā е сестра на Яма (бога на смъртта) и дъщеря на Сурья (Слънцето). Тя е втората по святост река в Индия след Ганга. Ямуна е особено свързана с Кришна — той е израснал в Бриндаван, на бреговете на Ямуна, и е играл с гопите там. Водата на Ямуна е тъмна на цвят, което е свързано с цвета на Кришна. Тази мантра се използва за пречистване, за преданост към Кришна, за свързване със свещената река. Тя се повтаря при посещение на Ямуна или при нужда от пречистване. Традиционно се повтаря 108 пъти. Много практикуващи я използват заедно с мантрата на Ганга.`,
  benefit: 'Пречистване, преданост към Кришна, свързване със свещената река.',
  repetitions: '108 пъти или при посещение на Ямуна',
