  tradition: 'Индуистка (Вайшнава)',
  deity: 'Радха',
  theme: 'love',
  meaning: 'Мантра, посветена на Радха — любимата на Кришна, символ на божествената любов. Радха е въплъщение на предаността и на женската енергия. Използва се за любов, за преданост и за отваряне на сърцето.',
  detailed: `Om Radhayai Namah е мантра, посветена на Радха — най-обичаната от всички гопи и главна любима на Кришна. В традицията на гаудия-вайшнавизма, Радха не е просто смъртна жена — тя е въплъщение на божествената енергия (хладини шакти) и на най-висшата форма на преданост. Нейната любов към Кришна е символ на връзката между душата и Бога. Тя е толкова важна, че Кришна се обръща към нея като „Радха-Кришна" — двете заедно са едно. Тази мантра се използва за любов, за преданост, за отваряне на сърцето. Тя се повтаря в петък или в деня на Кришна. Традиционно се повтаря 108 пъти. Много практикуващи я използват заедно с Hare Krishna Mantra — защото Радха и Кришна не могат да бъдат разделени.`,
  benefit: 'Любов, преданост, отваряне на сърцето.',
  repetitions: '108 пъти в петък или в деня на Кришна',
