  detailed: `Devi Suktam (известна още като Ratri Suktam или Vak Suktam) е химн от 10-та мандала на Риг Веда (10.125). Тя е една от най-важните ведически химни, посветени на Богинята — и един от най-старите текстове в света, в който Богинята говори за себе си като върховна сила. Химнът е изключително важен, защото показва, че почитането на Богинята-Майка датира още от ведически времена. В текста Деви казва: „Аз съм царицата, събирателката на съкровища, мъдрата, първата от тези, които са достойни за жертва." Тя е едновременно във всичко и отвъд всичко. Тя се движи с Рудрите, Васу, Адитиите, Вишведевите. Тя е това, което диша, това, което вижда, това, което чува. Тя е това, което създава вселената и това, което я разтваря. Химнът се рецитира в ритуалите на Деви, в шактийските традиции, в храмове на Богинята. Той се смята за източник на всички по-късни химни към Богинята — включително Деви Махатмя.`,
