  transliteration: 'Sahasraśīrṣaṃ Devaṃ Viśvākṣaṃ Viśvaśambhuvam Viśvaṃ Nārāyaṇaṃ Devam Akṣaraṃ Paramaṃ Padam',
  translation: 'Богът с хиляда глави, с очи навсякъде, който е благословия за вселената — Вселената е Нараяна, непреходният, върховната цел.',
