  deity: 'Нараяна (Вишну)',
  theme: 'devotion',
  meaning: 'Narayana Suktam е химн от Яджур Веда, който описва Нараяна като върховната реалност — присъстващ във всичко, отвъд всичко. Той е същността на всички същества и на цялата вселена.',
  detailed: `Narayana Suktam е химн от Тайтирия Упанишад (част от Кришна Яджур Веда) и е един от най-важните химни за вайшнавите. Той описва Нараяна като върховната реалност, която присъства във всичко. Той има хиляда глави, очи навсякъде, той е благословията на вселената. Всичко, което съществува, е Нараяна — той е вътре в сърцето на всеки, той е отвъд всичко. Химнът продължава с описание на Нараяна като светлина, която не може да бъде видяна с очите, но е вътрешното око на всичко. Той е това, което стои зад всички богове — Брахма, Шива, Индра. Той е върховната цел. Този химн се рецитира в ритуала Рудрам и в много вайшнавски практики. Много практикуващи го рецитират всеки ден. Той е дълъг (около 30 стиха), но може да се рецитира и в по-кратка форма.`,
  benefit: 'Преданост, осъзнаване на върховната реалност, духовно израстване.',
