  detailed: `Om Mani Padme Hum е най-известната будистка мантра в света и сърцето на тибетския будизъм. Тя е мантрата на Авалокитешвара (Chenrezig на тибетски), бодхисатва на състраданието. Мантрата е кратка, но съдържа цялото учение на Буда. Всяка сричка пречиства един от шестте свята на съществуването и един от шестте замърсителя: Om — гордостта, Ma — ревността, Ni — страстта, Pad — невежеството, Me — алчността, Hum — агресията. Практикуващите повтарят мантрата с броеница от 108 мъниста, докато визуализират светлина, излизаща от сърцето на Ченрезиг. Мантрата е гравирана върху камъни, молитвени колела, знамена — навсякъде в Тибет, Непал, Бутан, Монголия. Смята се, че тя е особено мощна в епохата на упадък (Kali Yuga) — най-лесният път към състрадание. Dalai Lama я препоръчва като основна мантра за всички будисти. Много практикуващи я повтарят 108 000 пъти като част от предварителните практики (ngöndro).`,
  benefit: 'Състрадание, пречистване на ума, вътрешен мир, просветление.',
