  transliteration: 'Oṃ Tāre Tuttāre Ture Mama Āyuḥ Puṇya Jñāna Puṣṭiṃ Kuru Svāhā',
  translation: 'Ом. Тара, велика Тара, бърза Тара — увеличи моя живот, заслуга и мъдрост, така да бъде.',
