  detailed: `White Tara Mantra е мантрата на Бялата Тара (Sitatara), която е по-медитативна и по-спокойна от Зелената Тара. Бялата Тара е свързана с дълголетие, здраве, заслуга (puṇya) и мъдрост (jñāna). Тя се изобразява с бяло тяло и със седем очи — две на лицето, две на дланите, две на стъпалата и едно на челото. Тези седем очи символизират нейното всевиждащо състрадание. Мантрата започва като Green Tara Mantra, но добавя молба: Mama Āyuḥ Puṇya Jñāna Puṣṭiṃ Kuru (увеличи моя живот, заслуга и мъдрост). Svāhā е свещен завършек. Бялата Тара се практикува за дълголетие, за изцеление, за премахване на препятствията пред духовния път. Тя е особено популярна сред възрастни хора и сред тези, които се грижат за болни. Традиционно се повтаря 108 пъти, най-добре с визуализация на бяла светлина, излизаща от Тара.`,
  benefit: 'Дълголетие, здраве, мъдрост, премахване на препятствия.',
