  detailed: `Universal Protection Mantra (I am protected. I am safe. I am loved.) е съвременна мантра за защита, която се използва при страх, при несигурност, при опасност. Тя съдържа три твърдения: I am protected (Аз съм защитен) — признание, че практикуващият е защитен от висша сила, от вселената, от собствения си вътрешен щит. I am safe (Аз съм в безопасност) — признание, че в този момент няма реална заплаха. I am loved (Аз съм обичан) — признание, че практикуващият не е сам, че е обичан от близки, от вселената, от себе си. Тази мантра се използва в съвременната духовна практика, в медитация, при тревожност, при паник атаки. Тя е особено популярна сред хора, които страдат от страх или от ПТСР. Много терапевти я препоръчват като част от лечението. Тя може да се рецитира, когато човек се почувства застрашен — тя носи усещане за защита и спокойствие. Смята се, че тя създава защитно поле около практикуващия.`,
