  detailed: `Universal Grounding Mantra (I am rooted. I am grounded. I am here.) е съвременна мантра за заземяване. Тя съдържа три твърдения, всяко от които връща практикуващия в настоящето. I am rooted (Аз съм вкоренен) — практикуващият си представя корени, които се спускат от тялото му дълбоко в земята. Те го държат стабилен, независимо от бурите на живота. I am grounded (Аз съм заземен) — практикуващият усеща тежестта на тялото си, контакта със стола, с пода, със земята. I am here (Аз съм тук) — практикуващият се връща в настоящия момент, оставяйки миналото и бъдещето настрана. Тази мантра се използва при тревожност, при паник атаки, при разсеяност, при деперсонализация. Тя е особено популярна сред хора, които работят високо в сгради, сред пилоти, сред хора със страх от височини. Много терапевти я препоръчват като част от лечението на тревожност. Тя може да се рецитира всеки ден, най-добре бос на земята. Смята се, че тя връща човека в тялото му и намалява тревожността.`,
  benefit: 'Заземяване, присъствие, намаляване на тревожност.',
  repetitions: '3, 9 или 108 пъти дневно, бос на земята',
  summary: 'Съвременна мантра за заземяване. Аз съм вкоренен, заземен и тук.'
