  translation: 'Освобождавам този ден. Приветствам почивката.',
  tradition: 'Универсална (съвременна)',
  deity: 'Универсално',
  theme: 'peace',
  meaning: 'Съвременна мантра за сън. Тя помага на практикуващия да освободи напрежението от деня и да приеме почивката. Използва се преди сън при безсъние.',
  detailed: `Universal Sleep Mantra (I release this day. I welcome rest.) е съвременна мантра за сън. Тя помага на практикуващия да освободи напрежението от деня и да приеме почивката. Първото изречение — I release this day (Освобождавам този ден) — практикуващият оставя настрана всичко, което се е случило през деня: успехи, провали, разговори, грижи. Той не ги носи в леглото. Второто изречение — I welcome rest (Приветствам почивката) — практикуващият се отваря към съня като дар, а не като задължение. Тази мантра се използва преди сън, при безсъние, при тревожни нощи. Тя е особено популярна сред хора, които страдат от безсъние или от претоварване. Много терапевти я препоръчват като част от хигиената на съня. Тя може да се рецитира, докато човек лежи в леглото, с дълбоко дишане. Смята се, че тя успокоява ума и помага за заспиване. Тя е пример за това как една кратка мантра може да подобри качеството на живота.`,
  benefit: 'Сън, почивка, освобождаване от напрежение.',
  repetitions: '1-3 пъти преди сън',
  summary: 'Съвременна мантра за сън. Освобождавам деня, приветствам почивката.'
