  theme: 'devotion',
  meaning: 'Съвременна мантра за утрото. Тя признава, че всеки ден е ново начало и изразява благодарност за този дар. Използва се сутрин при събуждане.',
  detailed: `Universal Morning Mantra (This is a new day. I am grateful.) е съвременна мантра за утрото. Тя признава, че всеки ден е ново начало — не продължение на вчерашния ден, а чиста страница. Практикуващият не носи вчерашните проблеми в новия ден. Второто изречение — I am grateful (Аз съм благодарен) — практикуващият изразява благодарност за новия ден, за новите възможности, за живота. Тази мантра се използва сутрин, веднага след събуждане. Тя е подобна на еврейската Modeh Ani, но в универсална форма. Тя е особено популярна сред хора, които искат да започнат деня с положителна нагласа. Много практикуващи я рецитират преди да станат от леглото. Смята се, че тя настройва деня към положителна посока. Тя може да се комбинира с усмивка и с дълбоко дишане. Смята се, че благодарността привлича още неща, за които да благодариш.`,
  benefit: 'Благодарност, ново начало, положителна нагласа.',
  repetitions: '1-3 пъти сутрин при събуждане',
